meta.text:
Three-way union merge of memory chunks. Pure; never touches the filesystem.
@param base the merge base (committed ancestor) — its records always survive (immutability).
@param ours our side (also the merge output target).
@param theirs their side.

Sanitize a raw Mule 3 attribute list. Same rules as the Mule 4 sanitizer, but `#[…]` payloads are
tagged `language: 'mel'` (Mule 3 has no DataWeave 2). Credential literals → `<redacted>`;
references + MEL expressions never carry a resolved secret value.

expr:
return (
    typeof rec.kind === 'string' &&
    typeof rec.subject === 'string' &&
    (RETIRING_KINDS as Set<string>).has(rec.kind)
  );

const bySubject = (side: Map<string, MemoryRecord>): Map<string, Set<MemoryDecisionKind>> => {
      const m = new Map<string, Set<MemoryDecisionKind>>();
      for (const rec of side.values()) {
        if (!isRetiringDecision(rec)) continue;
        const set = m.get(rec.subject) ?? new Set<MemoryDecisionKind>();
        set.add(rec.kind);
        m.set(rec.subject, set);
      }
      return m;
    };

warnings.push(
          `logical conflict: concurrent lifecycle events for subject ${subject} on both branches (ours=[${[...oKinds].join(',')}] theirs=[${[tKinds].join(',')}]) — both retained, review`,
        );

const lines = [...map.entries()]
    .sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
    .map(([, rec]) => JSON.stringify(rec));

const { attrs, expressions, name, configRef, target } = processAttributesMule3(
    el.attributes,
    el.startLine,
  );

const processor: MuleProcessor = {
    namespace: el.prefix,
    operation: el.local,
    semanticKind: classify(el.prefix, el.local, isSource),
    attributes: attrs,
    expressions,
    children,
    span: spanOf(el),
  };

diagnostics.push({
      code: 'mule:unknown-processor',
      severity: 'info',
      message: `Unrecognized Mule 3 processor ${el.prefix || ''}${el.prefix ? ':' : ''}${el.local} degraded to operation`,
    });

const processors = el.children
    .filter((c) => !isExceptionStrategy(c.local))
    .map((c) => buildProcessor(c, false, diagnostics));

const handler: MuleErrorHandler = {
    strategy: strategyOf(el.local),
    processors,
    span: spanOf(el),
  };

const resource =
        child.attributes.find((a) => a.local === 'resource')?.value ??
        child.attributes.find((a) => a.local === 'file')?.value ??
        '';

flows.push({
        name,
        kind: local === 'flow' ? 'flow' : 'subflow',
        processors,
        errorHandlers,
        span: spanOf(child),
      });

configurations.push({
      namespace: child.prefix,
      name: name ?? child.local,
      attributes: attrs,
      span: spanOf(child),
    });

return {
    dialect: 'mule3',
    imports,
    configurations,
    flows,
    diagnostics,
  };

signature:
isRetiringDecision(rec: MemoryRecord): rec is MemoryRecord & {
  kind: MemoryDecisionKind;
  subject: string;
}
